async function getOpenDate(number,key){let u=new URL(G2B);for(const [k,v] of Object.entries({ServiceKey:key,inqryDiv:'3',bizno:number,pageNo:'1',numOfRows:'10',type:'json'}))u.searchParams.set(k,v);let p=decodeG2B(await fetchText(u));if(!['00','0'].includes(p.code))return {date:'',status:'나라장터 오류 '+p.code+': '+p.msg};let matches=p.items.filter(x=>digits(x.bizno)===number);let dates=[...new Set(matches.map(x=>parseDate(x.opbizDt)).filter(Boolean))];return dates.length===1?{date:dates[0],status:'정상'}:{date:'',status:dates.length>1?'개업일 상충':'개업일 미확인'}}
